#pragma once
#include <algorithm>
#include <cstddef>
#include <optional>
#include <string>
#include <utility>
#include <vector>
#include "config.hpp"

namespace bench {

/// Evento del juego que se procesa por prioridad.
struct Event {
    std::string name;
    int priority = 0;   // 0..10, mayor = más urgente
    double time = 0.0;  // segundo de juego en el que debe procesarse
};

/// Cola de eventos del juego. Ver docs/tasks/CPP-301.md.
class EventQueue {
public:
    /// Encola un evento. Devuelve false si se rechaza (prioridad inválida o cola llena sin evento más prioritario).
    bool push(Event e) {
        if (e.priority < config::kMinPriority || e.priority > config::kMaxPriority) return false;
        if (m_items.size() >= config::kMaxQueuedEvents) {
            // El último es el menos prioritario (y, en empate, el que llegó último).
            if (m_items.back().priority >= e.priority) return false;
            m_items.pop_back();
        }
        // Inserta tras los de igual prioridad: mantiene FIFO en empates.
        auto pos = std::upper_bound(m_items.begin(), m_items.end(), e,
                                    [](const Event& a, const Event& b) { return a.priority > b.priority; });
        m_items.insert(pos, std::move(e));
        return true;
    }

    /// Saca el evento más prioritario. Devuelve std::nullopt si la cola está vacía.
    std::optional<Event> pop() {
        if (m_items.empty()) return std::nullopt;
        Event top = std::move(m_items.front());
        m_items.erase(m_items.begin());
        return top;
    }

    /// Cantidad de eventos encolados.
    std::size_t size() const { return m_items.size(); }

    /// Saca todos los eventos con time <= t, en orden de prioridad (FIFO en empates).
    /// Los demás eventos se quedan en la cola.
    std::vector<Event> drainUntil(double t) {
        std::vector<Event> out;
        auto it = m_items.begin();
        while (it != m_items.end()) {
            if (it->time <= t) {
                out.push_back(std::move(*it));
                it = m_items.erase(it);
            } else {
                ++it;
            }
        }
        return out;
    }

private:
    std::vector<Event> m_items;  // ordenado por prioridad descendente, FIFO en empates
};

}  // namespace bench
